// Compatibility route used by the current index.html live-goal button.
// It performs a real live-data check and never invents odds or statistics.
async function analyzeLiveFixture(fixture, liveOddsRow, statsRows, teamForms = null) {
  const stats = liveStatsMetrics(statsRows || [], fixture);
  const markets = oddsForFixture(liveOddsRow || null).filter(x =>
    ["İY 0.5 ÜST", "İY 1.5 ÜST", "MS 0.5 ÜST", "MS 1.5 ÜST", "MS 2.5 ÜST", "MS 3.5 ÜST", "MS 5.5 ÜST", "EV 0.5 ÜST", "DEP 0.5 ÜST", "EV 1.5 ÜST", "DEP 1.5 ÜST", "KG VAR"].includes(x.market)
  );
  const minute = Number(fixture.minute || 0);
  const homeGoals = Number(fixture.homeScore || 0), awayGoals = Number(fixture.awayScore || 0);
  const total = homeGoals + awayGoals;
  const phase = String(fixture.periodStatus || "").toUpperCase();
  const isFirstHalf = phase === "1H" || (!phase && minute < 45);
  const isHalftime = phase === "HT";
  const isSecondHalf = ["2H", "ET", "LIVE", "IN_PLAY"].includes(phase) || (!phase && minute >= 45);
  const formsAvailable = Boolean(teamForms?.home?.available && teamForms?.away?.available);
  const remaining = Math.max(1, 95 - minute);
  const sideLambda = (side, ownForm, opponentForm) => {
    const sidePressure = Number(side?.shotsOnTarget || 0) * 2.6 + Number(side?.totalShots || 0) * 0.42 + Number(side?.corners || 0) * 0.7;
    const pressureMultiplier = stats.available
      ? Math.max(0.50, Math.min(1.55, 0.62 + sidePressure / 11))
      : 0.75;
    const liveLambda = 1.25 * remaining / 90 * pressureMultiplier;
    const formRate = formsAvailable
      ? Math.max(0.08, 0.58 * Number(ownForm?.avgGoalsFor || 0) + 0.42 * Number(opponentForm?.avgGoalsAgainst || 0))
      : null;
    const formLambda = formRate == null ? null : formRate * remaining / 90 * pressureMultiplier;
    return Math.max(0.001, formLambda == null ? liveLambda : 0.55 * liveLambda + 0.45 * formLambda);
  };
  const lambdaHome = sideLambda(stats.home, teamForms?.home, teamForms?.away);
  const lambdaAway = sideLambda(stats.away, teamForms?.away, teamForms?.home);
  const homeNextGoalProbability = homeGoals > 0 ? 1 : poissonProbabilityAtLeast(1, lambdaHome, 0);
  const awayNextGoalProbability = awayGoals > 0 ? 1 : poissonProbabilityAtLeast(1, lambdaAway, 0);
  const homeScoresAgainProbability = poissonProbabilityAtLeast(1, lambdaHome, 0);
  const awayScoresAgainProbability = poissonProbabilityAtLeast(1, lambdaAway, 0);
  const anyNextGoalProbability = 1 - Math.exp(-(lambdaHome + lambdaAway));
  const activeStats = stats.available && (
    Number(stats.shotsOnTarget || 0) >= 2 || Number(stats.totalShots || 0) >= 8 || Number(stats.corners || 0) >= 6
  );
  const goalDirection = homeScoresAgainProbability >= awayScoresAgainProbability * 1.20 && homeScoresAgainProbability - awayScoresAgainProbability >= 0.08
    ? "home"
    : awayScoresAgainProbability >= homeScoresAgainProbability * 1.20 && awayScoresAgainProbability - homeScoresAgainProbability >= 0.08
      ? "away" : "balanced";
  const candidates = [];
  const evaluations = [];
  const rejected = { noLiveOdds: !liveOddsRow, noStats: !stats.available, noTeamForm: !formsAvailable, noMarket: markets.length === 0,
    lowOdds: 0, noValue: 0, settled: 0, wrongPeriod: 0, weakGoalSignal: 0, wrongGoalDirection: 0 };

  // Gol beklentisi önce doğrulanır. Zayıf canlı istatistikle yalnızca oran yüksek diye sinyal üretme.
  if (!stats.available || !activeStats || anyNextGoalProbability < 0.62 || minute < 10 || minute > 85 || isHalftime) {
    rejected.weakGoalSignal = 1;
  } else {
    for (const item of markets) {
      const odd = Number(item.odd);
      if (!Number.isFinite(odd) || odd < 1.50) { rejected.lowOdds++; continue; }
      if (liveMarketAlreadySettled(item.market, fixture)) { rejected.settled++; continue; }
      const ms = item.market.match(/^MS ([0-9]+(?:[.,][0-9]+)?) ÜST$/);
      const ht = item.market.match(/^İY ([0-9]+(?:[.,][0-9]+)?) ÜST$/);
      const isHomeMarket = item.market.startsWith("EV ");
      const isAwayMarket = item.market.startsWith("DEP ");
      if ((isFirstHalf && (!ht || isHomeMarket || isAwayMarket)) || (isSecondHalf && ht) || isHalftime) {
        rejected.wrongPeriod++; continue;
      }
      if (!isFirstHalf && !isSecondHalf) { rejected.wrongPeriod++; continue; }

      let modelProbability = 0;
      let lambdaUsed = null;
      let scenarioSide = null;
      if (isHomeMarket || isAwayMarket) {
        const isHome = isHomeMarket;
        const scored = isHome ? homeGoals : awayGoals;
        const lambda = isHome ? lambdaHome : lambdaAway;
        const line = item.market.includes("1.5") ? 2 : 1;
        const needed = Math.max(0, line - scored);
        if (needed === 0) { rejected.settled++; continue; }
        modelProbability = poissonProbabilityAtLeast(line, lambda, scored);
        lambdaUsed = lambda;
        scenarioSide = isHome ? "home" : "away";
        const sideGoalProbability = isHome ? homeScoresAgainProbability : awayScoresAgainProbability;
        const otherGoalProbability = isHome ? awayScoresAgainProbability : homeScoresAgainProbability;
        if (sideGoalProbability < 0.48 || (goalDirection !== "balanced" && scenarioSide !== goalDirection && sideGoalProbability < otherGoalProbability * 0.90)) {
          rejected.wrongGoalDirection++; continue;
        }
      } else if (item.market === "KG VAR") {
        if (homeGoals > 0 && awayGoals > 0) { rejected.settled++; continue; }
        modelProbability = (homeGoals > 0 ? 1 : homeScoresAgainProbability) * (awayGoals > 0 ? 1 : awayScoresAgainProbability);
        lambdaUsed = lambdaHome + lambdaAway;
      } else {
        const line = Number((ms || ht)[1].replace(',', '.'));
        const current = ms ? total : (fixture.htHomeScore != null && fixture.htAwayScore != null
          ? Number(fixture.htHomeScore) + Number(fixture.htAwayScore) : total);
        const timeLeft = ms ? remaining : Math.max(1, 45 - minute);
        const lambda = ms ? lambdaHome + lambdaAway : (lambdaHome + lambdaAway) * timeLeft / remaining;
        modelProbability = poissonProbabilityAtLeast(line, lambda, current);
        lambdaUsed = lambda;
        // Bir takımın gol atma olasılığı zayıfsa toplam gol pazarı da sırf fiyat avantajıyla seçilemez.
        if (current < Math.ceil(line) && anyNextGoalProbability < 0.62) { rejected.weakGoalSignal++; continue; }
      }

      const marketProbability = Number(item.probability) / 100;
      if (!Number.isFinite(marketProbability) || marketProbability <= 0 || marketProbability >= 1) { rejected.noMarket = true; continue; }
      const edge = modelProbability - marketProbability;
      const ev = modelProbability * odd - 1;
      evaluations.push({ market: item.market, odd, bookmaker: item.bookmaker, modelProbability, marketProbability, edge, ev,
        lambda: lambdaUsed, scenarioSide });

      // Değer eşiği: yalnızca istatistikle %5, istatistik + son 5 maçla %4 avantaj aranır.
      const minEdge = formsAvailable ? 0.04 : 0.05;
      const minEv = formsAvailable ? 0.04 : 0.05;
      const minProbability = item.market === "KG VAR" ? 0.42 : (isHomeMarket || isAwayMarket ? 0.48 : 0.60);
      if (modelProbability < minProbability || edge < minEdge || ev < minEv) { rejected.noValue++; continue; }

      // Skor senaryosuna uymayan pazar seçilmesin. Örn. deplasman golü daha olasıysa evin ikinci golü ana tercih olamaz.
      let directionBonus = 0;
      if (goalDirection !== "balanced") {
        if (scenarioSide && scenarioSide !== goalDirection) { rejected.wrongGoalDirection++; continue; }
        if (!scenarioSide && item.market !== "KG VAR") directionBonus = -0.035;
      }
      const score = edge * 100 + ev * 100 + modelProbability * 20 + directionBonus * 100;
      const confidence = (
        stats.available && activeStats && formsAvailable &&
        edge >= 0.10 && ev >= 0.10 && modelProbability >= 0.70
      ) ? "HIGH" : (
        stats.available && activeStats &&
        edge >= 0.06 && ev >= 0.06 && modelProbability >= minProbability + 0.05
      ) ? "MEDIUM" : "LOW";
      candidates.push({ market: item.market, bookmaker: item.bookmaker, modelProbability, marketProbability, edge, ev,
        odd, confidence, statsAvailable: true, teamFormAvailable: formsAvailable,
        minEdgeRequired: minEdge, minEVRequired: minEv, scenarioSide, selectionScore: score });
    }
  }
  candidates.sort((a,b) => b.selectionScore - a.selectionScore || (b.ev + b.edge) - (a.ev + a.edge));
  evaluations.sort((a,b) => (b.ev + b.edge) - (a.ev + a.edge) || b.ev - a.ev);
  const chosen = candidates[0] || null;
  const directionLabel = goalDirection === "home" ? "Ev sahibi golü daha olası" : goalDirection === "away" ? "Deplasman golü daha olası" : "Gol yönü net değil";
  return {
    fixtureId: fixture.id, currentScore: `${homeGoals}-${awayGoals}`, minute, periodStatus: phase,
    mainPick: chosen?.market || null, alternative: candidates[1]?.market || null,
    source: chosen?.bookmaker || null, valueScore: chosen?.ev ?? null, edge: chosen?.edge ?? null,
    oddsTiming: liveOddsRow ? "live" : "unavailable",
    stats: { available: stats.available, totalShots: stats.totalShots, shotsOnTarget: stats.shotsOnTarget, corners: stats.corners,
      pressure: Number((stats.pressure || 0).toFixed(1)), home: stats.home, away: stats.away },
    teamForm: { available: formsAvailable, homeSample: teamForms?.home?.sampleSize || 0, awaySample: teamForms?.away?.sampleSize || 0 },
    goalScenario: { direction: goalDirection, label: directionLabel,
      homeNextGoalProbability: Number((homeScoresAgainProbability * 100).toFixed(1)),
      awayNextGoalProbability: Number((awayScoresAgainProbability * 100).toFixed(1)),
      anyNextGoalProbability: Number((anyNextGoalProbability * 100).toFixed(1)),
      activeStats },
    marketEvaluations: evaluations,
    goalSignal: { level: chosen ? "Değer adayı" : "Tercih yok", score: chosen ? Math.round(chosen.edge * 100) : 0,
      note: chosen ? `${directionLabel}; canlı oran, canlı istatistik${formsAvailable ? " ve son 5 maç formu" : ""} birlikte değerlendirildi.`
        : (!liveOddsRow ? "Gerçek canlı oran bulunamadı." : isHalftime ? "Devre arası; canlı tercih bekletildi." :
          "Gol olasılığı, takım yönü, canlı istatistik ve değer eşiklerini birlikte karşılayan tercih bulunmadı.") },
    oddsBasis: liveOddsRow ? "Yalnızca gerçek canlı oranlar kullanıldı; maç önü oranı yedek yapılmadı." : "Canlı oran bulunamadı; maç önü oranı kullanılmadı.",
    reasonCounts: rejected,
    note: chosen ? `En güçlü canlı aday: ${chosen.market}; gol senaryosu: ${directionLabel}. Kesin sonuç değildir.`
      : "Maç tarandı ancak gol beklentisi veya uygun pazar yeterince doğrulanmadı; tercih üretilmedi."
  };
}

app.get("/api/match/:id/live-goal-analysis", async (req, res) => {
  try {
    const fixtureId = Number(req.params.id);
    if (!Number.isInteger(fixtureId) || fixtureId <= 0) return res.status(400).json({ error: "Geçersiz maç kimliği." });
    const row = await getFixtureForLiveAnalysis(fixtureId);
    if (!row) return res.status(404).json({ error: "Maç verisi bulunamadı." });
    const fixture = normalizeProviderMatch(row);
    if (fixture.status !== "LIVE") return res.status(409).json({ error: "Bu maç API tarafından canlı olarak işaretlenmiyor." });
    const [statsPayload, oddsPayload] = await Promise.all([
      cachedProviderRequest(`stats:${fixtureId}`, `/fixtures/statistics?fixture=${fixtureId}`, 15000).catch(e => { console.warn(`[Live analysis] stats failed fixture=${fixtureId}: ${e.message}`); return { response: [] }; }),
      cachedProviderRequest(`odds-live-fixture:${fixtureId}`, `/odds/live?fixture=${fixtureId}`, 10000).catch(e => { console.warn(`[Live analysis] live odds failed fixture=${fixtureId}: ${e.message}`); return { response: [] }; })
    ]);
    let liveOddsRow = (oddsPayload.response || []).find(x => Number(x.fixture?.fixture?.id ?? x.fixture?.id ?? x.fixtureId ?? x.id) === fixtureId) || null;
    if (!liveOddsRow) {
      try { const all = await cachedProviderRequest("odds-live-all", "/odds/live", 10000); liveOddsRow = (all.response || []).find(x => Number(x.fixture?.fixture?.id ?? x.fixture?.id ?? x.fixtureId ?? x.id) === fixtureId) || null; } catch {}
    }
    return res.json(await analyzeLiveFixture(fixture, liveOddsRow, statsPayload.response || []));
  } catch (error) {
    const message = String(error?.message || error);
    const limited = /429|rate.?limit|quota|istek sınırı/i.test(message);
    res.status(limited ? 429 : 502).json({ error: limited ? "API kotası/sınırı nedeniyle canlı analiz şu an alınamıyor." : "Canlı analiz alınamadı.", detail: message });
  }
});

app.get("/api/match/:id/analyze", async (req, res) => {
  try {
    const payload = await cachedProviderRequest(`fixture:${req.params.id}`, `/fixtures?id=${encodeURIComponent(req.params.id)}`, 15000);
    const row = payload.response?.[0];
    if (!row) return res.status(404).json({ error: "Maç verisi bulunamadı." });

    const match = normalizeProviderMatch(row);
    // WinScope test modu: canlı maç kartta görünür, analiz ise tamamen maç önü verisiyle yapılır.
    // Canlı oranlar ve canlı istatistikler bu endpointte kesinlikle kullanılmaz.
    const prematchFixture = {
      ...match,
      status: "NS",
      minute: null,
      homeScore: 0,
      awayScore: 0,
      htHomeScore: null,
      htAwayScore: null
    };

    const [prematchRow, homeForm, awayForm] = await Promise.all([
      getOddsForFixture(match.id, match.fixtureDate ? String(match.fixtureDate).slice(0, 10) : null).catch(e => {
        console.warn(`[Prematch analysis] odds failed fixture=${match.id}: ${e.message}`); return null;
      }),
      fetchTeamRecentForm(match.homeId, match.id, match.leagueId, match.season, "home"),
      fetchTeamRecentForm(match.awayId, match.id, match.leagueId, match.season, "away")
    ]);
    const forms = { home: homeForm, away: awayForm };
    const scores = scorePrediction(prematchFixture, homeForm, awayForm, null, prematchRow);

    // Tercih yalnızca maç önü piyasasında gerçekten bulunan oranlardan seçilir.
    const chosen = prematchRow
      ? chooseSupportedMarket(prematchRow, "prematch", prematchFixture, forms, null, prematchRow)
      : null;
    const ftMatch = String(scores.fullTimeScore || "").match(/(\d+)\s*[-:]\s*(\d+)/);
    const scoreSuggestsBtts = Boolean(ftMatch && Number(ftMatch[1]) > 0 && Number(ftMatch[2]) > 0);
    const alternative = chosen
      ? chooseSupportedMarket(prematchRow, "prematch", prematchFixture, forms, null, prematchRow, chosen.market, scoreSuggestsBtts ? "KG VAR" : null)
      : null;

    const percentages = analysisPercentages(prematchRow, homeForm, awayForm);
    const marketNames = oddsForFixture(prematchRow).map(x => x.market);
    const marketAvailable = name => marketNames.includes(name);
    res.json({
      fixtureId: match.id,
      matchStatus: match.status,
      analysisMode: "PREMATCH_ONLY",
      halfTimeScore: scores.halfTimeScore,
      fullTimeScore: scores.fullTimeScore,
      alternativeFullTimeScore: scores.alternativeFullTimeScore || "Alternatif skor hesaplanamadı",
      scoreBasis: scores.scoreBasis || "Maç önü oranları ve erişilebilen son 5 maç formu",
      mainPick: chosen?.market || "Maç önü oranlarından doğrulanmış tercih bulunamadı",
      alternative: alternative?.market || "Doğrulanmış alternatif bulunamadı",
      livePick: "Canlı analiz kapalı — maç önü analizi",
      livePickBasis: "Canlı oran ve canlı istatistik kullanılmıyor.",
      marketPercentages: percentages,
      markets: {
        ht1x2: marketAvailable("İY 1X2"),
        ft1x2: marketAvailable("MS 1X2"),
        ht05: marketAvailable("İY 0.5 ÜST"),
        ht15: marketAvailable("İY 1.5 ÜST"),
        btts: marketAvailable("KG VAR"),
        ms15: marketAvailable("MS 1.5 ÜST"),
        ms25: marketAvailable("MS 2.5 ÜST"),
        ms35: marketAvailable("MS 3.5 ÜST"),
        ms55: marketAvailable("MS 5.5 ÜST"),
        ah05: marketAvailable("AH -0.5")
      },
      note: prematchRow
        ? `${chosen?.bookmaker || "Maç önü oran kaydı"} ve erişilebilen takım formu değerlendirildi. Ham oranlar arayüzde gösterilmez.`
        : "Bu maç için API-Football üzerinden maç önü oran kaydı alınamadı. Skor tahmini yalnızca mevcut takım formu verisiyle üretilebilir; oran dayanaklı tercih üretilmedi.",
      oddsBasis: prematchRow
        ? "Yalnızca API-Football maç önü oranları; canlı oranlar kullanılmadı."
        : "Maç önü oranı bulunamadı.",
      htMarketAlreadyHit: false
    });
  } catch (e) {
    res.status(502).json({ error: "Maç önü analizi üretilemedi.", detail: e.message });
  }
});

